const discipline: TechnologyInput[] = [
  tech({ id: "rejuv-rehab-cancer-rehabilitation", name: "Cancer rehabilitation: the discipline that puts function back", sections: [REJ, SUP], status: "established", wikipedia: W("Physical_medicine_and_rehabilitation"), tags: T("moderate"),
    tldr: "Cancer rehabilitation is the medical speciality that treats what treatment leaves behind: weakness, a stiff shoulder, a swallow that no longer works, a bladder that leaks, a limb that swells. It is delivered by a named set of professions, it has randomised evidence behind several of its parts, and in the largest study to measure it only three in ten of the impairments that needed it were treated.",
    summary: "Cancer rehabilitation is not a synonym for exercise and it is not physiotherapy alone. It is a model of care in which a person's function is treated as a clinical problem with a diagnosis, a measurement and a treatment plan, the same way a blood count or a scan is.\n\nWho does it. A cancer rehabilitation team is built from six professions, and in most countries each is a separate referral. Rehabilitation medicine, called physiatry in the United States and rehabilitation medicine in the United Kingdom, is the medical speciality that diagnoses the impairment and prescribes the programme. Physiotherapy treats strength, range of movement, balance, breathing and the pelvic floor. Occupational therapy treats the activities themselves: dressing, washing, cooking, working, driving, and the fatigue management that makes those possible. Speech and language therapy treats swallowing and voice, which after head and neck treatment are the same therapist's problem. Dietetics treats the weight, the protein intake and the feeding tube. Clinical psychology treats the fear, the low mood and the body image that determine whether any of the rest is attempted. Lymphoedema services, prosthetics and orthotics services and vocational rehabilitation sit alongside them.\n\nWhat it is for. Silver and colleagues set out the organising idea in 2013: screen for impairment all the way along the care pathway and treat what is found, rather than waiting for disability to arrive. Their review states the case plainly: \"Research has also demonstrated that the majority of cancer survivors will have significant impairments and that these often go undetected and/or untreated, and consequently may result in disability.\" They also note that \"more cancer survivors have a reduced health-related quality of life as a result of physical impairments than due to psychological ones\", which is the finding that most changes where attention should go.\n\nWhat it achieves, and what it does not. The parts of the discipline have been tested separately rather than together, and this page grades each of them in its own record: prehabilitation before surgery, swallowing therapy during head and neck radiotherapy, pulmonary rehabilitation after lung resection, pelvic floor training after prostate surgery, vestibular rehabilitation after skull base surgery. Some of those are strong, one of them is a well-conducted negative trial, and several rest on single small studies. No randomised trial has tested the whole multidisciplinary model against usual care with survival or disability as its endpoint, and it is unlikely one ever will, because the parts are not withheld in the same way a drug is. Occupational therapy is the clearest example of the evidence problem: a 2021 systematic review of occupational therapy after discharge found nine studies covering 531 people with cancer, and concluded that \"Small sample sizes and methodological quality precluded any formal analysis\".\n\nWhat comes back, and when: that depends entirely on which impairment, and each record here states it. The general shape is that function treated early recovers further than function treated late, and that the single biggest determinant of outcome in the published data is not the therapy but whether the referral was made at all.",
    principle: "An impairment is a diagnosable, measurable problem with a treatment. Rehabilitation medicine works by naming it (shoulder abduction to sixty degrees, six-minute walk distance of 280 metres, a swallow that penetrates the larynx), prescribing a graded programme against that measure, and reassessing. The measurement is what distinguishes it from advice to keep active.",
    strengths: ["Treats the problems that patients rank highest after treatment: strength, mobility, swallowing, continence", "Several components have randomised evidence of their own", "Measurable: the same instruments used in trials can be used in clinic"],
    limitations: ["No randomised trial of the whole multidisciplinary model against usual care", "The occupational therapy evidence base is too small to pool", "Referral, not therapy, is where most people are lost"],
    cancers: ["breast-hr-positive", "head-and-neck", "colorectal", "nsclc", "prostate", "sarcoma"], technologies: ["survivorship-care-plan", "exercise-prescription-after-cancer", "rejuv-rehab-prospective-surveillance", "rejuv-rehab-provision-gap", "rejuv-rehab-prehabilitation-evidence", "rejuv-rehab-commissioning-inequity", "oncology-nutrition", "geriatric-assessment", "psycho-oncology", "oncology-nursing", "rejuv-rehab-balance-vestibular"], terms: ["late-effects", "quality-of-life"], bottlenecks: ["b-survivorship", "b-toxicity-qol"], related: ["idea-acc-return-to-work-rehabilitation", "idea-acc-cognitive-rehabilitation-after-chemotherapy"],
    links: [SILVER_2013, CHEVILLE_2008, STOUT_PSM_2012, doi("Occupational therapy intervention for cancer patients following hospital discharge: a systematic review (Aust Occup Ther J 2021)", "10.1111/1440-1630.12750")] }),

  tech({ id: "rejuv-rehab-prospective-surveillance", name: "Prospective surveillance: looking for the problem before it becomes a disability", sections: [REJ, SUP], status: "emerging", since: 2012, wikipedia: W("Cancer_survivor"), tags: T("moderate"),
    tldr: "The usual model waits for a patient to complain, by which time an arm has been swollen for a year. The prospective surveillance model measures function before treatment starts and again at set points afterwards, so a small problem is found while it is still small. One costing study put the price of managing early arm swelling at 636 dollars a year against 3,125 dollars for late swelling.",
    summary: "The model was written down in 2012 by a multidisciplinary group convened around breast cancer, and published as a set of papers in the journal Cancer. Its proposal is simple and structural: take a baseline measurement of function before treatment begins, repeat it at defined points during and after treatment, and refer the moment a measure moves. The authors list the impairments it is meant to catch, which is a useful list in itself: \"pain, fatigue, upper-extremity dysfunction, lymphedema, weakness, joint arthralgia, neuropathy, weight gain, cardiovascular effects, and osteoporosis\".\n\nThe cost argument came from the same group. Comparing a surveillance programme with the traditional referral-when-it-is-bad model for breast cancer related arm swelling, and costing both from the 2009 Medicare physician fee schedule, they estimated 636.19 dollars per patient per year to manage early-stage swelling found by surveillance against 3,124.92 dollars per patient per year to treat late-stage swelling found the old way. That is a modelled comparison, not a trial, and the authors say so: they call for analysis of indirect costs and utility before claiming cost-effectiveness.\n\nThe electronic version is where the field has moved. An electronic prospective surveillance model asks patients to complete short impairment questionnaires at set points on a phone or web form; a score that crosses a threshold produces self-management material, a community programme or a referral. The REACH system running across four Canadian centres covers breast, colorectal, lymphoma and head and neck cancer and follows patients up to two years after treatment. Its own protocol is careful about the state of the evidence: it says randomised trials show these systems \"can effectively manage cancer-related impairments\", and then that they \"are not routinely embedded into practice and evidence-based approaches to implement them are limited\".\n\nThe implementation problem is the real one. A 2023 account of running the model in one breast centre describes what it took: clinical pathways, order sets in the electronic record, automated referrals, new staffing models and changed clinic workflows. Its first sentence about uptake is the honest one, that the model \"is empirically validated and feasible in practice\" but that \"implementation into cancer care delivery has languished\".\n\nWhat comes back, and when: nothing, by itself. Surveillance treats no one. Its claim is that the same treatment started earlier works better and costs less, which is well supported for arm swelling and plausible but less tested for the rest of the list.",
    principle: "Impairments after cancer treatment follow a gradient from reversible to fixed. Measuring function at fixed intervals converts the question from whether a patient complains loudly enough to whether a number has moved, which detects the reversible phase. The mechanism is the same as any screening programme, and so are its weaknesses: it finds things that would not have mattered, and it only works if a service exists to refer into.",
    strengths: ["A baseline measurement makes later change interpretable", "Electronic delivery scales without a clinic visit", "A modelled fivefold cost difference for early versus late arm swelling"],
    limitations: ["Screening without a rehabilitation service to refer into changes nothing", "The cost figure is a model, not a trial result", "Uptake has been slow for fourteen years, which is itself evidence about feasibility"],
    cancers: ["breast-hr-positive", "colorectal", "head-and-neck", "dlbcl"], technologies: ["rejuv-rehab-cancer-rehabilitation", "epro-symptom-monitoring", "survivorship-care-plan", "lymphoedema-surgery-and-early-detection", "lymphoedema-decongestive-therapy", "remote-patient-monitoring", "rejuv-rehab-provision-gap"], terms: ["late-effects", "quality-of-life"], bottlenecks: ["b-survivorship"], related: ["idea-acc-return-to-work-rehabilitation"],
    links: [STOUT_PSM_2012, doi("Breast cancer-related lymphedema: comparing direct costs of a prospective surveillance model and a traditional model of care (Phys Ther 2012)", "10.2522/ptj.20100167"), doi("Upper-body morbidity after breast cancer within a prospective surveillance model of care (Cancer 2012)", "10.1002/cncr.27467"), doi("Implementation of an electronic prospective surveillance model for cancer rehabilitation: protocol (BMJ Open 2024)", "10.1136/bmjopen-2024-090449"), doi("Implementing and sustaining a breast cancer prospective surveillance rehabilitation program (J Cancer Surviv 2023)", "10.1007/s11764-022-01304-x")] }),

  tech({ id: "rejuv-rehab-provision-gap", name: "The gap between the rehabilitation people need and the rehabilitation they are offered", sections: [REJ, SUP], status: "established", wikipedia: W("Cancer_survivor"), tags: T("moderate"),
    tldr: "This is the measured part. Among 163 women with advanced breast cancer, 92 per cent had at least one physical impairment and 530 impairments were found; 30 per cent of those needing rehabilitation got it. In an Irish cancer centre in 2025, 71 per cent of 660 patients reported at least one specialist rehabilitation need and 36 per cent of those with a need had seen the relevant professional.",
    summary: "The gap has been measured several times, in different countries and decades, and the numbers are consistent enough to quote.\n\nThe benchmark study is Cheville and colleagues, published in 2008. They took a consecutive sample of 163 community-dwelling women with metastatic breast cancer, assessed each with a physical examination, a six-minute walk test and standard function scales, and had a panel of rehabilitation physicians and therapists decide what each impairment needed. The results: \"Ninety-two percent of patients (150 of 163) had at least one physical impairment. Among 530 identified impairments, 484 (92%) required a physical rehabilitation intervention and 469 (88%) required physical therapy (PT) and/or occupational therapy (OT). Only 30% of impairments requiring rehabilitation services and 21% of those requiring PT/OT received treatment.\" The setting mattered more than the impairment: a problem found while the patient was in hospital had an odds ratio of 87.9 for getting any rehabilitation at all, and 558.8 for getting physiotherapy or occupational therapy, compared with a problem found in clinic. The authors' conclusion names the inequity as well: \"Undertreatment was particularly prominent among minority and socioeconomically disadvantaged groups.\"\n\nThe contemporary figure comes from Ireland. A prospective survey of 660 consecutive outpatients at a comprehensive cancer centre in June and July 2025 used the Macmillan Holistic Needs Assessment to capture unmet needs. On average 71 per cent of patients reported at least one specialist allied health professional need and 49 per cent reported at least two. Only 36 per cent of patients with a perceived need reported having seen the relevant professional since diagnosis.\n\nEurope as a whole is no better organised. The INSPIRE project compared official documents and clinical practice in the United Kingdom, France, Denmark, Norway and Italy through a document analysis of 23 documents, 22 stakeholder interviews and a survey of 225 professionals, and found limited integration of rehabilitation into cancer care in both the documents and the practice, present \"within limited organisations in secondary healthcare systems, without widespread adoption\".\n\nSpain gives the figure for a single profession. In the DAMA cohort of 2,235 women diagnosed with breast cancer in the Barcelona hospital network, among women reporting chronic and acute symptoms \"only between 20 and 35% of women visited physiotherapist\", and two in three said they had received insufficient information about medical care and rehabilitation.\n\nWhat the United Kingdom figure is. This is the gap in the gap, and it is worth naming rather than filling with a number from somewhere else. There is no published national audit of how many people in the United Kingdom who need cancer rehabilitation receive it. What exists is a policy layer, including the Macmillan Cancer Support prehabilitation guidance developed with the Royal College of Anaesthetists and the National Institute for Health Research Cancer and Nutrition Collaboration, and single-service evaluations such as Active Together in Sheffield, whose own protocol notes that evidence for multimodal rehabilitation is increasing while \"The translation of that evidence into practice is less advanced\". A reader asking how likely they are to be offered rehabilitation in an English hospital cannot be given a number from a national source, and should not be given one from anywhere else.",
    principle: "Two things have to be true for a patient to receive rehabilitation: someone has to notice the impairment, and a service has to exist to receive the referral. The published data separate those failures. Cheville's inpatient odds ratios show the noticing problem, because the same impairment in the same patient was treated in hospital and ignored in clinic. The Irish and Spanish figures show the service problem.",
    strengths: ["Measured repeatedly, in different systems, with consistent results", "Separates the referral failure from the service failure", "Uses instruments that services already hold"],
    limitations: ["No national audit figure for the United Kingdom", "Most studies are single-centre and cross-sectional", "Need is self-reported in the newer studies and panel-assessed in the older one, so the figures are not directly comparable"],
    cancers: ["breast-hr-positive", "colorectal", "head-and-neck", "nsclc", "dlbcl"], technologies: ["rejuv-rehab-cancer-rehabilitation", "rejuv-rehab-commissioning-inequity", "rejuv-rehab-prospective-surveillance", "survivorship-care-plan", "financial-navigation"], terms: ["late-effects", "quality-of-life"], bottlenecks: ["b-survivorship", "b-patient-voice"], related: ["idea-acc-return-to-work-rehabilitation"],
    links: [CHEVILLE_2008, IRELAND_UNMET_2026, doi("Integration of palliative rehabilitation in cancer care: a multinational mixed method study (BMC Palliat Care 2024)", "10.1186/s12904-024-01586-1"), doi("Social inequalities in the use of physiotherapy in women diagnosed with breast cancer in Barcelona: DAMA cohort (Breast Cancer Res Treat 2024)", "10.1007/s10549-023-07191-9"), doi("Embedding multimodal rehabilitation within routine cancer care in Sheffield: the Active Together service evaluation protocol (J Phys Act Health 2024)", "10.1123/jpah.2023-0622")] }),
];

